// VULN-020 fix: intervalId typed and stored correctly
private intervalId: ReturnType<typeof setInterval> | null = null;

stopHostScreenUpdate(): void {
  if (this.intervalId !== null) {
    clearInterval(this.intervalId);
    this.intervalId = null;
  }
}
// BUT: stopHostScreenUpdate() is NEVER CALLED anywhere in the codebase.
// app.component.ts onBrowserClose(): calls logout() but NOT stopHostScreenUpdate()
// storage.service.ts setNotConnected(): clears tokens but NOT stopHostScreenUpdate()
// NavigationService: no ngOnDestroy() — polling continues for app lifetime
